package tw.xiaoxin.relens;
import java.text.SimpleDateFormat;import java.util.*;
final class AppLog {private static final int MAX=1000;private static final ArrayDeque<String> lines=new ArrayDeque<>();interface Listener{void onLogChanged();}private static final ArrayList<Listener> listeners=new ArrayList<>();static synchronized void addListener(Listener l){if(!listeners.contains(l))listeners.add(l);}static synchronized void removeListener(Listener l){listeners.remove(l);}static void i(String t,String m){add("I",t,m);}static void w(String t,String m){add("W",t,m);}static void e(String t,String m){add("E",t,m);}static void e(String t,Throwable error){StringBuilder message=new StringBuilder();Throwable current=error;int depth=0;while(current!=null&&depth++<8){if(message.length()>0)message.append(" <- ");message.append(current.getClass().getName());if(current.getMessage()!=null&&!current.getMessage().isEmpty())message.append(": ").append(current.getMessage());if(current.getCause()==current)break;current=current.getCause();}add("E",t,message.toString());}private static synchronized void add(String l,String t,String m){String time=new SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS",Locale.ROOT).format(new Date());lines.addLast(time+" "+l+"/"+t+": "+sanitize(m));while(lines.size()>MAX)lines.removeFirst();for(Listener x:new ArrayList<>(listeners))x.onLogChanged();}static synchronized String export(){StringBuilder b=new StringBuilder("RE Lens operation log\n");for(String s:lines)b.append(s).append('\n');return b.toString();}static synchronized void clear(){lines.clear();for(Listener l:new ArrayList<>(listeners))l.onLogChanged();}private static String sanitize(String s){return s==null?"":s.replaceAll("(?i)(password|passphrase)=\\S+","$1=<redacted>");}}
